function source(title, organisationOrAuthor, urlOrReference, sourceType, relevantClaim) {
  return Object.freeze({ title, organisationOrAuthor, urlOrReference, publicationDate: null, accessDate: ACCESS_DATE, sourceType, reviewStatus: "approved", relevantClaim });
}

function q(stableSuffix, sourceKey, countryScope, subregionScope, communityScope, category, questionText, correct, distractors, explanation, sensitivityNotes = null) {
  return Object.freeze({ stableSuffix, sourceKey, countryScope, subregionScope, communityScope, category, questionText, correct, distractors, explanation, sensitivityNotes });
}

function rotate(values, amount) {
  return [...values.slice(amount), ...values.slice(0, amount)];
}

function makeQuestion(spec, index) {
  const optionTexts = rotate([spec.correct, ...spec.distractors], index % 4);
  const answerOptions = optionTexts.map((text, optionIndex) => ({ id: `o${optionIndex + 1}`, text }));
  const acceptedId = answerOptions.find((option) => option.text === spec.correct).id;
  const difficulty = ["introductory", "intermediate", "introductory", "intermediate", "advanced"][index % 5];
  return {
    stableId: `west_${spec.stableSuffix}`,
    version: 1,
    region: "west",
    countryScope: spec.countryScope,
    subregionScope: spec.subregionScope,
    communityScope: spec.communityScope,
    category: spec.category,
    difficulty,
    questionKind: "single",
    questionText: spec.questionText,
    answerOptions,
    acceptedAnswers: [[acceptedId]],
    explanation: spec.explanation,
    sources: [sources[spec.sourceKey]],
    reviewer: spec.sensitivityNotes ? RESEARCH_REVIEWER : null,
    reviewDate: spec.sensitivityNotes ? ACCESS_DATE : null,
    sensitivityNotes: spec.sensitivityNotes,
    language: "en",
    locale: "en",
    lifecycleStatus: "draft",
    publishedAt: null,
    retiredAt: null,
    validFrom: null,
    validUntil: null,
    scoringWeight: 1,
    imageProvenance: [],
    audioProvenance: [],
  };
}

function csvCell(value) {
  const safe = neutralizeCsvFormula(String(value ?? ""));
  return /[",\r\n]/.test(safe) ? `"${safe.replaceAll('"', '""')}"` : safe;
}

function csv(rows) {
  return `${rows.map((row) => row.map(csvCell).join(",")).join("\n")}\n`;
}

function tally(values) {
  return [...values.reduce((map, value) => map.set(value, (map.get(value) || 0) + 1), new Map()).entries()].sort(([a], [b]) => a.localeCompare(b));
}

function table(rows) {
  return rows.map(([name, count]) => `| ${name} | ${count} |`).join("\n");
}

const document = validateQuestionBankDocument({ schemaVersion: "question-bank-v1", questions: specs.map(makeQuestion) });
if (document.questions.length < 65) throw new Error(`expected_at_least_65_candidates_got_${document.questions.length}`);
const legacy = await buildLegacyQuestionBankDocument();
const duplicateReport = previewQuestionBankImport(document, legacy);
const sourceEntries = Object.entries(sources);
const sourceCounts = new Map(sourceEntries.map(([key]) => [key, specs.filter((spec) => spec.sourceKey === key).length]));
const difficultyCounts = tally(document.questions.map((question) => question.difficulty));
const categoryCounts = tally(document.questions.map((question) => question.category));
const countryOccurrences = tally(document.questions.flatMap((question) => question.countryScope.split("; ")));
const scopeCounts = tally(document.questions.map((question) => question.countryScope.includes(";") ? "multi-country" : question.communityScope ? "country-and-community" : "country-only"));
const sensitiveQuestions = document.questions.filter((question) => question.sensitivityNotes);

const reviewRows = [["stableId", "version", "countryScope", "subregionScope", "communityScope", "category", "difficulty", "questionText", "acceptedAnswer", "lifecycleStatus", "specialistReviewRequired", "sensitivityNotes", "sourceTitle", "sourceUrl", "humanDecision", "humanReviewer", "humanReviewDate", "humanReviewNotes"]];
for (const question of document.questions) {
  const accepted = question.acceptedAnswers[0].map((id) => question.answerOptions.find((option) => option.id === id).text).join(" | ");
  reviewRows.push([question.stableId, question.version, question.countryScope, question.subregionScope, question.communityScope, question.category, question.difficulty, question.questionText, accepted, question.lifecycleStatus, question.sensitivityNotes ? "yes" : "no", question.sensitivityNotes, question.sources[0].title, question.sources[0].urlOrReference, "pending", "", "", ""]);
}

const sourceRows = [["sourceId", "title", "organisationOrAuthor", "urlOrReference", "sourceType", "accessDate", "candidateCount", "relevantClaim"]];
sourceEntries.forEach(([key, item], index) => sourceRows.push([`WA-S${String(index + 1).padStart(2, "0")}`, item.title, item.organisationOrAuthor, item.urlOrReference, item.sourceType, item.accessDate, sourceCounts.get(key), item.relevantClaim]));

const coverage = `# West Africa draft question-bank coverage\n\nGenerated ${ACCESS_DATE}. These are research candidates, not culturally approved or publishable questions.\n\n## Totals\n\n- Candidates: ${document.questions.length}\n- Lifecycle: draft (${document.questions.length})\n- Unique authoritative sources: ${sourceEntries.length}\n- Candidates flagged for specialist review: ${sensitiveQuestions.length}\n- Media assets: 0\n\n## Difficulty\n\n| Difficulty | Count |\n| --- | ---: |\n${table(difficultyCounts)}\n\n## Category\n\n| Category | Count |\n| --- | ---: |\n${table(categoryCounts)}\n\n## Country occurrence\n\nMulti-country questions count once for each named country.\n\n| Country | Candidate occurrences |\n| --- | ---: |\n${table(countryOccurrences)}\n\n## Scope\n\n| Scope type | Count |\n| --- | ---: |\n${table(scopeCounts)}\n\n## Communities and local scopes represented\n\n${[...new Set(document.questions.map((question) => question.communityScope).filter(Boolean))].sort().map((scope) => `- ${scope}`).join("\n")}\n`;

const underrepresented = `# West Africa under-representation report\n\nCandidate occurrence counts are a research-coverage measure, not population weights or cultural rankings.\n\n## Lowest coverage\n\n${countryOccurrences.filter(([, count]) => count < 4).map(([country, count]) => `- **${country}: ${count}.** A local cultural institution or community specialist should identify additional everyday, contemporary and hospitality topics before approval targets are set.`).join("\n")}\n\n## Known collection gaps\n\n- Everyday greetings and etiquette need language-specific sources and community review; unsupported translations were deliberately excluded.\n- Well-supported proverb candidates remain a gap because translations and attribution require language specialists.\n- Liberia, Sierra Leone and Guinea-Bissau need stronger national-institution sourcing beyond the authoritative museum and UNESCO records used here.\n- Rural and urban contemporary life outside the named heritage practices needs locally authored evidence.\n- Wedding and courtship coverage is intentionally limited to one Mauritanian zaffa candidate pending specialist review; no practice is generalized across West Africa.\n`;

const issueLog = `# West Africa cultural-review issue log\n\nAll ${document.questions.length} candidates remain draft. Source approval in the import contract means that the reference passed research-source screening; it is not cultural approval of the question.\n\n## Specialist review queue (${sensitiveQuestions.length})\n\n${sensitiveQuestions.map((question) => `- **${question.stableId}:** ${question.sensitivityNotes}`).join("\n")}\n\n## Collection-wide review questions\n\n- Confirm preferred community names, diacritics and English renderings with reviewers from the named communities.\n- Confirm that public-source descriptions of initiatory and sacred practices do not cross local disclosure boundaries.\n- Review distractors for unintended political, religious or ethnic implications.\n- Review the Cidade Velha candidate with a trauma-informed Cabo Verdean historian.\n- Review gender descriptions in the attiéké and Sande records as source-specific observations, not prescriptions.\n- Confirm whether “Eid al-Adha” or the locally used “Eid el-Kabir” is preferred for the Kano Durbar candidate.\n- Recheck every URL and source claim at the human-review date.\n`;

const duplicateAnalysis = `# West Africa duplicate and near-duplicate analysis\n\nCompared ${document.questions.length} draft candidates against each other and the verified 60-question transitional catalogue using the Prompt 20 import preview.\n\n- Exact duplicate question texts: ${duplicateReport.exactDuplicates.length}\n- Token near-duplicate pairs at the engine threshold: ${duplicateReport.nearDuplicates.length}\n- Writes performed: ${duplicateReport.writesPerformed}\n\n## Exact duplicates\n\n${duplicateReport.exactDuplicates.length ? duplicateReport.exactDuplicates.map((item) => `- ${item}`).join("\n") : "None detected."}\n\n## Near duplicates\n\n${duplicateReport.nearDuplicates.length ? duplicateReport.nearDuplicates.map((item) => `- ${item.left} / ${item.right}: ${item.similarity}`).join("\n") : "None detected at the configured threshold."}\n\nHuman reviewers should still assess conceptual overlap, especially Kente, balafon, food and language topics that also appear more generally in the transitional catalogue.\n`;

await mkdir(outputDir, { recursive: true });
await Promise.all([
  writeFile(resolve(outputDir, "west-africa-draft-v1.json"), `${JSON.stringify(document, null, 2)}\n`, "utf8"),
  writeFile(resolve(outputDir, "west-africa-cultural-review.csv"), csv(reviewRows), "utf8"),
  writeFile(resolve(outputDir, "west-africa-source-register.csv"), csv(sourceRows), "utf8"),
  writeFile(resolve(outputDir, "west-africa-review-issues.md"), issueLog, "utf8"),
  writeFile(resolve(outputDir, "west-africa-coverage.md"), coverage, "utf8"),
  writeFile(resolve(outputDir, "west-africa-underrepresented.md"), underrepresented, "utf8"),
  writeFile(resolve(outputDir, "west-africa-duplicate-analysis.md"), duplicateAnalysis, "utf8"),
]);

console.log(JSON.stringify({ candidates: document.questions.length, sources: sourceEntries.length, specialistReview: sensitiveQuestions.length, difficulty: Object.fromEntries(difficultyCounts), exactDuplicates: duplicateReport.exactDuplicates.length, nearDuplicates: duplicateReport.nearDuplicates.length }, null, 2));
